<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {api} from '../../core/http';
import {useCasesStore} from '../cases/store';
import {useAccountStore} from '../../stores/account';
import AppBottomSheet from '../../components/AppBottomSheet.vue';
import AppState from '../../components/AppState.vue';
import ClientCalendarPanel from '../../components/ClientCalendarPanel.vue';
import {loadWorkspace} from '../../services/clientWorkspace';
import {expandCourses} from '../../services/timetable';

const props=defineProps<{caseId:string;tasks:any[]}>();
const account=useAccountStore();
const calendarConsent=ref(false),cases=useCasesStore();
const weekdays=['周一','周二','周三','周四','周五','周六','周日'];
const now=new Date(),weekStart=ref(startOfWeek(now)),selected=ref(key(now));
const items=ref<any[]>([]),preview=ref<any>(null),loading=ref(false),working=ref(false),error=ref(''),message=ref('');
const formOpen=ref(false),editingId=ref('');
const form=ref<any>({title:'',kind:'busy',starts_at:'',ends_at:'',task_id:'',repeat_count:1});
const preferences=ref({work_start_hour:8,work_end_hour:21,buffer_minutes:0,daily_max_minutes:240});
const planning=ref({task_id:'',duration_minutes:30,splittable:false,min_chunk_minutes:30,max_chunk_minutes:60,importance:0,preference:0});
async function savePlanning(){working.value=true;resetNotice();try{const {task_id,...body}=planning.value;await api('/api/v1/tasks/'+task_id+'/planning',{method:'PUT',body:JSON.stringify(body)});preview.value=null;message.value='步骤排程设置已保存，请重新预览。'}catch(e:any){error.value=e?.message||'设置保存失败'}finally{working.value=false}}
const days=computed(()=>Array.from({length:7},(_,index)=>{const value=new Date(weekStart.value);value.setDate(value.getDate()+index);return {value,key:key(value),label:weekdays[index],day:value.getDate(),month:value.getMonth()+1,isToday:key(value)===key(now)}}));
const weekLabel=computed(()=>{const first=days.value[0],last=days.value[6];return first.month===last.month?`${first.month}月${first.day}日—${last.day}日`:`${first.month}月${first.day}日—${last.month}月${last.day}日`});
const dayItems=computed(()=>items.value.filter(item=>key(new Date(item.starts_at))===selected.value));
const formTitle=computed(()=>editingId.value?'编辑安排':'添加安排');
const kindLabels:Record<string,string>={course:'课程',busy:'忙碌',task:'任务'};
const reasonLabels:Record<string,string>={already_scheduled:'已有安排',blocked_by_predecessor:'等待前置任务',deadline_passed:'截止时间已过',outside_preview_window:'不在预览范围',invalid_deadline:'截止时间格式无效',no_available_slot:'没有满足截止时间的空闲时段'};

function startOfWeek(value:Date){const result=new Date(value.getFullYear(),value.getMonth(),value.getDate());result.setDate(result.getDate()-((result.getDay()+6)%7));return result}
function key(value:Date){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`}
function inputValue(value:Date){const offset=value.getTimezoneOffset()*60000;return new Date(value.getTime()-offset).toISOString().slice(0,16)}
function displayTime(value:string){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))}
function displayDateTime(value:string){return new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value))}
function selectedRange(){let start=new Date(`${selected.value}T09:00:00`);if(selected.value===key(new Date())&&new Date()>start){start=new Date();start.setSeconds(0,0);start.setMinutes(Math.ceil(start.getMinutes()/30)*30)}const end=new Date(start);end.setHours(end.getHours()+1);return [inputValue(start),inputValue(end)]}
function resetNotice(){error.value='';message.value=''}
async function load(){if(!account.signedIn)return;loading.value=true;error.value='';try{const start=new Date(days.value[0].value);const end=new Date(start);end.setDate(end.getDate()+7);const params=new URLSearchParams({from:start.toISOString(),to:end.toISOString()});items.value=await api('/api/v1/schedule?'+params.toString())}catch(e:any){error.value=e?.message||'日程读取失败'}finally{loading.value=false}}
function openNew(){resetNotice();editingId.value='';const [starts_at,ends_at]=selectedRange();form.value={title:'',kind:'busy',starts_at,ends_at,task_id:'',repeat_count:1};formOpen.value=true}
function openEdit(item:any){resetNotice();editingId.value=item.id;form.value={title:item.title,kind:item.kind,starts_at:inputValue(new Date(item.starts_at)),ends_at:inputValue(new Date(item.ends_at)),task_id:item.task_id||'',repeat_count:1};formOpen.value=true}
async function save(){working.value=true;resetNotice();try{const body={title:form.value.title.trim(),kind:form.value.kind,starts_at:new Date(form.value.starts_at).toISOString(),ends_at:new Date(form.value.ends_at).toISOString(),case_id:props.caseId||null,task_id:form.value.kind==='task'?form.value.task_id||null:null};await api(editingId.value?'/api/v1/schedule/items/'+editingId.value:Number(form.value.repeat_count)>1?'/api/v1/schedule/series':'/api/v1/schedule/items',{method:editingId.value?'PATCH':'POST',body:JSON.stringify(Number(form.value.repeat_count)>1?{...body,count:Number(form.value.repeat_count),timezone:'Asia/Shanghai'}:body)});formOpen.value=false;message.value=editingId.value?'安排已更新。':'安排已保存。';await load()}catch(e:any){error.value=e?.message||'日程保存失败'}finally{working.value=false}}
async function remove(itemId=editingId.value){if(!itemId||!window.confirm('删除这条安排？'))return;working.value=true;try{await api('/api/v1/schedule/items/'+itemId,{method:'DELETE'});formOpen.value=false;message.value='安排已删除。';await load()}catch(e:any){error.value=e?.message||'删除失败'}finally{working.value=false}}
async function makePreview(){if(!props.caseId)return;working.value=true;resetNotice();try{if(cases.selected?.relevance==='FALSE')throw Error('本机资料与资格条件不符，请先核对，不生成自动排程。');const start=new Date(),end=new Date(start);end.setDate(end.getDate()+14);const workspace=await loadWorkspace(account.user?.id||'offline');const blocks=expandCourses(workspace.courses,key(start),key(end));if(blocks.length&&!calendarConsent.value)throw Error('请明确确认发送本机课表占用时段');preview.value=await api('/api/v1/schedule/drafts',{method:'POST',body:JSON.stringify({case_id:props.caseId,window_start:start.toISOString(),window_end:end.toISOString(),timezone:'Asia/Shanghai',preferences:preferences.value,calendar_blocks:blocks.map(b=>({id:b.id,starts_at:b.starts_at,ends_at:b.ends_at,evidence_ids:b.evidence_ids})),calendar_consent:calendarConsent.value,calendar_revision:workspace.revision})});if(!preview.value.suggestions.length)message.value='当前没有可确认的排程建议。'}catch(e:any){error.value=e?.message||'排程预览失败'}finally{working.value=false}}
async function confirmDraft(){if(!preview.value?.draft_id||!window.confirm('确认将整份排程草稿保存到当前账户？'))return;working.value=true;resetNotice();try{const workspace=await loadWorkspace(account.user?.id||'offline');if(preview.value.calendar_revision!==undefined&&preview.value.calendar_revision!==workspace.revision)throw Error('本机资料或课表已变化，请重新预览');await api('/api/v1/schedule/drafts/'+preview.value.draft_id+'/commit',{method:'POST',body:JSON.stringify({consent:true,calendar_revision:workspace.revision})});preview.value=null;message.value='整份排程已保存。';await load()}catch(e:any){error.value=e?.message||'草稿确认失败，请重新预览'}finally{working.value=false}}
async function toggleLock(item:any){working.value=true;resetNotice();try{await api('/api/v1/schedule/items/'+item.id+'/lock',{method:'POST',body:JSON.stringify({locked:!item.locked})});preview.value=null;await load()}catch(e:any){error.value=e.message}finally{working.value=false}}
async function shiftWeek(offset:number){const value=new Date(weekStart.value);value.setDate(value.getDate()+offset*7);weekStart.value=value;selected.value=key(value);preview.value=null;await load()}
async function today(){weekStart.value=startOfWeek(now);selected.value=key(now);await load()}
watch(()=>props.caseId,()=>{preview.value=null;load()},{immediate:true});
</script>

<template>
  <section class="plan-schedule" aria-label="日程安排">
    <div v-if="error" class="notice notice--danger">{{error}}</div><div v-if="message" class="notice notice--success">{{message}}</div>
    <ClientCalendarPanel :tasks="tasks"/>
    <label v-if="account.signedIn" class="consent-row"><input v-model="calendarConsent" type="checkbox">同意发送本机课表占用时段用于此次排程（不含课程名称和原文件）</label>
    <AppState v-if="!account.signedIn" title="登录后管理日程" description="课程、忙碌时间和任务安排会按账户保存。"><RouterLink class="button button--primary" to="/auth/login">登录</RouterLink></AppState>
    <template v-else>
      <header class="schedule-toolbar"><button type="button" aria-label="上一周" @click="shiftWeek(-1)">‹</button><div><h2>{{weekLabel}}</h2><p>选择日期查看并编辑当天安排</p></div><div class="schedule-toolbar__actions"><button type="button" @click="today">今天</button><button type="button" aria-label="下一周" @click="shiftWeek(1)">›</button></div></header>
      <div class="schedule-week" role="tablist" aria-label="选择日期"><button v-for="day in days" :key="day.key" :class="{active:selected===day.key,today:day.isToday}" type="button" role="tab" :aria-selected="selected===day.key" @click="selected=day.key"><span>{{day.label.replace('周','')}}</span><b>{{day.day}}</b><small>{{items.filter(item=>key(new Date(item.starts_at))===day.key).length||''}}</small></button></div>
      <div class="schedule-legend"><span><i class="schedule-swatch schedule-swatch--course"></i>课程</span><span><i class="schedule-swatch schedule-swatch--busy"></i>忙碌</span><span><i class="schedule-swatch schedule-swatch--task"></i>任务</span></div>
      <AppState v-if="loading" kind="loading" title="正在读取日程"/>
      <div v-else-if="dayItems.length" class="schedule-day-list"><article v-for="item in dayItems" :key="item.id" :class="`schedule-event schedule-event--${item.kind}`" @click="openEdit(item)" @keydown.enter.prevent="openEdit(item)" tabindex="0" role="button"><span>{{displayTime(item.starts_at)}}—{{displayTime(item.ends_at)}}</span><b>{{item.title}}</b><small>{{kindLabels[item.kind]}} · {{item.locked?'已锁定':'点击编辑'}}</small><button type="button" :disabled="working" @click.stop="toggleLock(item)">{{item.locked?'解锁安排':'锁定安排'}}</button></article></div>
      <AppState v-else title="当天没有安排" description="可以添加课程、忙碌时间，或预览任务排程。"/>
      <details class="surface-card"><summary>填写步骤耗时与拆分方式</summary><form class="form-card" @submit.prevent="savePlanning"><label>排程步骤<select v-model="planning.task_id" required aria-label="排程步骤"><option value="">请选择步骤</option><option v-for="task in tasks" :key="task.id" :value="task.id">{{task.title}}</option></select></label><label>估计耗时分钟<input v-model.number="planning.duration_minutes" type="number" min="1" max="1440" required></label><label><input v-model="planning.splittable" type="checkbox">允许分段安排</label><label>最小片段分钟<input v-model.number="planning.min_chunk_minutes" type="number" min="30" max="240" step="30"></label><label>最大片段分钟<input v-model.number="planning.max_chunk_minutes" type="number" min="30" max="240" step="30"></label><label>重要性（0至1）<input v-model.number="planning.importance" type="number" min="0" max="1" step="0.1"></label><label>执行偏好（0至1）<input v-model.number="planning.preference" type="number" min="0" max="1" step="0.1"></label><button class="button button--secondary" :disabled="working||!planning.task_id">保存步骤排程设置</button><p>用户估计会生成填写依据；已有安排须先移除再修改。</p></form></details><fieldset class="form-card"><legend>排程偏好（仅用于本次草稿）</legend><label>每天开始小时<input v-model.number="preferences.work_start_hour" type="number" min="0" max="22"></label><label>每天结束小时<input v-model.number="preferences.work_end_hour" type="number" min="1" max="23"></label><label>安排间缓冲分钟<input v-model.number="preferences.buffer_minutes" type="number" min="0" max="120"></label><label>每日任务分钟上限<input v-model.number="preferences.daily_max_minutes" type="number" min="30" max="1380"></label><p>课程及忙碌时段始终保留；耗时为估计，草稿须人工核对。</p></fieldset><div class="schedule-actions"><button class="button button--secondary" type="button" @click="openNew">添加安排</button><button class="button button--primary" type="button" :disabled="working||!caseId" @click="makePreview">{{working?'处理中…':'预览任务排程'}}</button></div>
      <section v-if="preview" class="schedule-preview"><header><div><span class="text-label">排程建议</span><h3>{{preview.suggestions.length}} 项可安排</h3></div><small>草稿状态变化后须重新预览</small><button class="button button--primary" :disabled="working||!preview.suggestions.length" @click="confirmDraft">确认整份排程</button></header><article v-for="item in preview.suggestions" :key="item.task_id+item.starts_at"><div><b>{{item.title}}</b><small v-if="item.segment_count>1">第{{item.segment_index}}/{{item.segment_count}}段</small><small>{{displayDateTime(item.starts_at)}}—{{displayTime(item.ends_at)}} · {{item.scheduled_minutes}} 分钟</small></div></article><div v-if="preview.unscheduled.length" class="schedule-unscheduled"><b>未安排</b><p v-for="item in preview.unscheduled" :key="item.task_id">{{item.title}}：{{reasonLabels[item.reason]||item.detail}}</p></div></section>
    </template>
    <AppBottomSheet :open="formOpen" :title="formTitle" @close="formOpen=false"><form class="form-card schedule-form" @submit.prevent="save"><label>标题<input v-model="form.title" required maxlength="200"></label><label>类型<select v-model="form.kind"><option value="busy">忙碌时间</option><option value="course">课程</option><option value="task">知事任务</option></select></label><label v-if="form.kind==='task'">关联步骤<select v-model="form.task_id" required><option value="">请选择步骤</option><option v-for="task in tasks" :key="task.id" :value="task.id">{{task.title}}</option></select></label><label v-if="!editingId&&form.kind!=='task'">连续每周次数<input v-model.number="form.repeat_count" type="number" min="1" max="13"></label><label>开始时间<input v-model="form.starts_at" type="datetime-local" required></label><label>结束时间<input v-model="form.ends_at" type="datetime-local" required></label><div class="button-row"><button v-if="editingId" class="button button--danger" type="button" :disabled="working" @click="remove()">删除</button><button class="button button--primary" :disabled="working">{{working?'保存中…':'保存'}}</button></div></form></AppBottomSheet>
  </section>
</template>
